import json,re
f='d7486560-6acc-4665-90c6-35b26df35cff.jsonl'
pats=[r'rev(ision)? ?2',r'trimmed',r'3\.7',r'06-08',r'out of 69',r'second',r'asymmetric']
for line in open(f,encoding='utf-8'):
    try:o=json.loads(line)
    except:continue
    ts=o.get('timestamp');role=o.get('type')
    m=o.get('message',{});c=m.get('content') if isinstance(m,dict) else None
    texts=[]
    if isinstance(c,str):texts=[c]
    elif isinstance(c,list):
        for b in c:
            if isinstance(b,dict):
                if b.get('type')=='text':texts.append(b['text'])
                elif b.get('type')=='tool_result':
                    cc=b.get('content');texts.append(cc if isinstance(cc,str) else json.dumps(cc))
    for t in texts:
        for p in pats:
            for mm in re.finditer(p,t,re.I):
                s=t[max(0,mm.start()-160):mm.end()+160].replace('\n',' ')
                print(f'[{ts} {role} /{p}/] {s}\n')
EOF

